using System.ComponentModel;
using System.Net.Http.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ApiTools
{
    [McpServerTool, Description("Fetches a post by ID from the external API.")]
    public static async Task<string> GetPost(
        IHttpClientFactory httpClientFactory,
        [Description("The numeric ID of the post to retrieve.")] int id)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var post = await client.GetFromJsonAsync<Post>($"posts/{id}");

        return post is null
            ? $"Post {id} not found."
            : $"Title: {post.Title}\n\nBody: {post.Body}";
    }

    private sealed record Post(int Id, int UserId, string Title, string Body);
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizationPrompts
{
    [McpServerPrompt, Description("Creates a prompt to summarize the provided text.")]
    public static string Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional maximum number of sentences.")] int maxSentences = 3)
    {
        return $"Please summarize the following text in at most {maxSentences} sentences:\n\n{text}";
    }
}

